import { CATALOGUE_FAMILIES, CATALOGUE_FORM_CONDITIONS, CATALOGUE_RECORDS } from '../content/catalogue';

// Canonical reference catalogue: the Pokémon the Pokédex can *describe*, as opposed to the ones
// the survivor game plays. Generated by scripts/catalogue-pack.mjs (via scripts/build-content.mjs)
// from the PokéAPI CSV snapshot pinned in content/catalogue.json.
//
// This is deliberately a separate authority from `SPECIES` (src/rules/species.ts), not an extension
// of it. A catalogue record carries canonical facts only — ordered typing, form identity, raw
// measurements with their qualifiers, species family edges — and no sprite, cry, learnset, spawn
// entry, behaviour or role. Nothing in src/sim/, src/world/, src/render/ or src/ui/ reads this
// module: a reference record inside `SPECIES` would join `all-wild` spawn pools and move every
// replay hash (the habitat navigation profiles are frozen constants since the hero-shooter pivot,
// src/world/habitat/mode.ts `VALIDATED_PROFILES`). Keeping the two sets apart
// makes that impossible rather than something to remember.
//
// The families here are canonical relationships. The game's paced progression is `evolvesTo` /
// `evolveLevel` on a SpeciesDef, which stays the only thing progression, lineage and the squad
// read; a canonical edge never becomes an in-run evolution.

/** How the source classifies a `pokemon` record against its species' default form. */
type FormStatus =
  | 'species-default'
  | 'persistent-alternate'
  | 'persistent-fusion'
  | 'regional'
  | 'temporary'
  | 'out-of-battle-build';

/** `selected` was picked by the research tables; `family-or-form` came in with a family or form. */
type Inclusion = 'selected' | 'family-or-form';

/** `listed` is a published figure. `lower-bound` is a published minimum (Gigantamax heights). */
type HeightKind = 'listed' | 'lower-bound';

/** `listed` is a published figure. `unknown-placeholder` is a stand-in for an unknown mass. */
type WeightKind = 'listed' | 'unknown-placeholder';

export interface CatalogueRecord {
  /** PokéAPI `pokemon` slug — the same identity namespace as `SpeciesDef.id`. */
  id: string;
  pokemonId: number;
  species: string;
  speciesId: number;
  /** English species name. Form records share their species' name; `form.label` separates them. */
  name: string;
  /** Official type names in source slot order. Order is display-visible; never sort these. */
  types: string[];
  form: { slug: string; id: number; label: string; status: FormStatus };
  /** Official body shape (PokéAPI `pokemon_shapes` identifier); src/rules/shapes.ts maps it to a measurement axis. */
  shape: string | null;
  /** Raw source extent in decimetres. Read it through `heightMeters` so the qualifier travels. */
  heightDm: number;
  heightKind: HeightKind;
  /** Raw source mass in hectograms. Read it through `weightKilograms`, which rejects placeholders. */
  weightHg: number;
  weightKind: WeightKind;
  inclusion: Inclusion;
  /** PokéAPI evolution-chain id; the key into `CATALOGUE_FAMILIES`. */
  chainId: number;
}

export interface CatalogueFamily {
  chainId: number;
  root: string;
  /** Every species in the chain, including the root. */
  species: string[];
  /** Directed parent → child species edges, every branch kept. */
  edges: [string, string][];
  singleton: boolean;
}

/** An explicit form or regional restriction on a species edge, kept as a source reference. */
export interface CatalogueFormCondition {
  chainId: number;
  parent: string;
  child: string;
  requiredForm: { slug: string | null; id: number } | null;
  evolvedForm: { slug: string | null; id: number } | null;
  region: string | null;
  versionGroups: string[];
}

export const CATALOGUE: CatalogueRecord[] = CATALOGUE_RECORDS;
export const FAMILIES: CatalogueFamily[] = CATALOGUE_FAMILIES;
export const FORM_CONDITIONS: CatalogueFormCondition[] = CATALOGUE_FORM_CONDITIONS;

export const CATALOGUE_BY_ID: Record<string, CatalogueRecord> = Object.fromEntries(CATALOGUE.map((r) => [r.id, r]));

/** Every record of a species, default first: the default form plus any alternate varieties. */
export const CATALOGUE_BY_SPECIES: Record<string, CatalogueRecord[]> = (() => {
  const out: Record<string, CatalogueRecord[]> = {};
  for (const r of CATALOGUE) (out[r.species] ??= []).push(r);
  for (const list of Object.values(out)) list.sort((a, b) => Number(b.form.status === 'species-default') - Number(a.form.status === 'species-default') || a.pokemonId - b.pokemonId);
  return out;
})();

/** The catalogue record for a PokéAPI `pokemon` slug, or null when it is outside the catalogue. */
export function catalogueRecord(id: string): CatalogueRecord | null {
  return CATALOGUE_BY_ID[id] ?? null;
}

/** A species' default `pokemon` record. For 9 species its slug is not the species slug
 *  (aegislash → aegislash-shield, tatsugiri → tatsugiri-curly, …), so never guess by name. */
export function defaultRecordOf(species: string): CatalogueRecord | null {
  return CATALOGUE_BY_SPECIES[species]?.find((r) => r.form.status === 'species-default') ?? null;
}

/** The complete canonical family a species belongs to, with every branch. */
export function familyOfSpecies(species: string): CatalogueFamily | null {
  return FAMILIES.find((f) => f.species.includes(species)) ?? null;
}

/** Every canonical child of a species. Branching parents have more than one (Tyrogue has three). */
export function childrenOfSpecies(species: string): string[] {
  return familyOfSpecies(species)?.edges.filter(([p]) => p === species).map(([, c]) => c) ?? [];
}

/** A species' canonical parent, or null at the root of its family. */
export function parentOfSpecies(species: string): string | null {
  return familyOfSpecies(species)?.edges.find(([, c]) => c === species)?.[0] ?? null;
}

/** The explicit form/region restrictions recorded for a species edge. */
export function formConditionsFor(parent: string, child: string): CatalogueFormCondition[] {
  return FORM_CONDITIONS.filter((c) => c.parent === parent && c.child === child);
}

/** Extent in metres, with the qualifier kept: a Gigantamax figure is a published minimum. */
export function heightMeters(record: CatalogueRecord): { m: number; lowerBound: boolean } {
  return { m: record.heightDm / 10, lowerBound: record.heightKind === 'lower-bound' };
}

/** Mass in kilograms, or null when the source value is a placeholder for an unknown mass.
 *  Returning null keeps a placeholder out of any weight rule: 10,000 hg would read as
 *  "Massive" and Eternamax's 0 hg as "Weightless" (see `weightClass` in ./species). */
export function weightKilograms(record: CatalogueRecord): number | null {
  return record.weightKind === 'unknown-placeholder' ? null : record.weightHg / 10;
}

export const CATALOGUE_TOTALS = {
  records: CATALOGUE.length,
  species: Object.keys(CATALOGUE_BY_SPECIES).length,
  varieties: CATALOGUE.length - Object.keys(CATALOGUE_BY_SPECIES).length,
  families: FAMILIES.length,
  edges: FAMILIES.reduce((n, f) => n + f.edges.length, 0),
  singletons: FAMILIES.filter((f) => f.singleton).length,
  conditions: FORM_CONDITIONS.length,
} as const;
